//! Talking to a guest over SSH.
//!
//! The guest's host key was generated by META and is the only one accepted, so there
//! is no first connection to trust blindly. Forwarding of agents, ports and displays
//! is off unless asked for.

use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

use crate::config::{VmConfig, VmError};
use crate::quote::command_line;

pub const SSH: &str = "/usr/bin/ssh";
/// What ssh itself returns when the connection fails.
pub const SSH_FAILURE: i32 = 255;

#[derive(Debug, Clone)]
pub struct Connection {
    directory: PathBuf,
    port: u16,
    user: String,
    name: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Options {
    /// Allocate a terminal, so that signals typed there reach the program.
    pub terminal: bool,
    /// Let the program open windows on the host's X display. It can then see and
    /// control everything on that display.
    pub x11: bool,
    pub connect_timeout: u32,
}

impl Connection {
    pub fn new(directory: &Path, config: &VmConfig) -> Self {
        Self {
            directory: directory.to_owned(),
            port: config.ssh_port,
            user: config.owner.clone(),
            name: config.name.clone(),
        }
    }

    /// Arguments for ssh(1), without the remote command.
    pub fn arguments(&self, options: Options) -> Vec<String> {
        let path = |name: &str| self.directory.join(name).display().to_string();
        let mut args: Vec<String> = ["-F", "/dev/null", "-i"].map(str::to_owned).to_vec();
        args.push(path("client_key"));
        let timeout = if options.connect_timeout == 0 {
            10
        } else {
            options.connect_timeout
        };
        for option in [
            format!("UserKnownHostsFile={}", path("known_hosts")),
            "GlobalKnownHostsFile=/dev/null".into(),
            "StrictHostKeyChecking=yes".into(),
            "HostKeyAlgorithms=ssh-ed25519".into(),
            "IdentitiesOnly=yes".into(),
            "PasswordAuthentication=no".into(),
            "KbdInteractiveAuthentication=no".into(),
            "ForwardAgent=no".into(),
            "ClearAllForwardings=yes".into(),
            "PermitLocalCommand=no".into(),
            "LogLevel=ERROR".into(),
            format!("HostKeyAlias=meta-linux-{}", self.name),
            format!("ConnectTimeout={timeout}"),
        ] {
            args.push("-o".into());
            args.push(option);
        }
        args.push("-p".into());
        args.push(self.port.to_string());
        args.push(if options.terminal { "-t" } else { "-T" }.into());
        args.push(if options.x11 { "-X" } else { "-x" }.into());
        args.push(format!("{}@127.0.0.1", self.user));
        args
    }

    fn ssh(&self, options: Options, remote: &str) -> Command {
        let mut command = Command::new(SSH);
        command.args(self.arguments(options)).arg("--").arg(remote);
        command
    }

    /// A connection that runs `command` with the caller's standard streams.
    pub fn command(
        &self,
        options: Options,
        environment: &[(String, String)],
        command: &[String],
    ) -> Command {
        self.ssh(options, &command_line(None, environment, command))
    }

    /// Runs a program with the caller's standard streams and returns its exit code.
    pub fn run(
        &self,
        options: Options,
        directory: Option<&str>,
        environment: &[(String, String)],
        command: &[String],
    ) -> Result<i32, VmError> {
        let remote = command_line(directory, environment, command);
        let status = self
            .ssh(options, &remote)
            .status()
            .map_err(|e| VmError::Guest(format!("cannot start ssh: {e}")))?;
        Ok(status.code().unwrap_or(SSH_FAILURE))
    }

    /// Runs a program and returns its exit code and output.
    pub fn capture(&self, timeout: u32, command: &[&str]) -> Result<(i32, String), VmError> {
        let command: Vec<String> = command.iter().map(|c| (*c).to_owned()).collect();
        let options = Options {
            connect_timeout: timeout,
            ..Options::default()
        };
        let output = self
            .ssh(options, &command_line(None, &[], &command))
            .stdin(Stdio::null())
            .output()
            .map_err(|e| VmError::Guest(format!("cannot start ssh: {e}")))?;
        let mut text = String::from_utf8_lossy(&output.stdout).into_owned();
        if !output.status.success() {
            text.push_str(&String::from_utf8_lossy(&output.stderr));
        }
        Ok((output.status.code().unwrap_or(SSH_FAILURE), text))
    }

    /// Copies a host file into the guest, readable and executable by its owner.
    pub fn upload(&self, host: &Path, guest: &str) -> Result<(), VmError> {
        let file = std::fs::File::open(host).map_err(|source| VmError::Io {
            path: host.display().to_string(),
            source,
        })?;
        // The path is an argument of sh, not part of its script.
        let script =
            "umask 077; mkdir -p \"$(dirname \"$1\")\" && cat > \"$1\" && chmod 700 \"$1\"";
        let command: Vec<String> = ["sh", "-c", script, "sh", guest]
            .iter()
            .map(|s| (*s).to_owned())
            .collect();
        let output = self
            .ssh(Options::default(), &command_line(None, &[], &command))
            .stdin(Stdio::from(file))
            .output()
            .map_err(|e| VmError::Guest(format!("cannot start ssh: {e}")))?;
        if output.status.success() {
            Ok(())
        } else {
            let detail = String::from_utf8_lossy(&output.stderr);
            Err(VmError::Guest(format!(
                "copying {} failed: {}",
                host.display(),
                detail.trim()
            )))
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::tests::sample;

    #[test]
    fn connections_are_pinned_and_forward_nothing() {
        let connection = Connection::new(Path::new("/d"), &sample());
        let text = connection.arguments(Options::default()).join(" ");
        for expected in [
            "StrictHostKeyChecking=yes",
            "ForwardAgent=no",
            "ClearAllForwardings=yes",
            "HostKeyAlias=meta-linux-debian",
            "-p 22010",
            " -T -x alice@127.0.0.1",
        ] {
            assert!(text.contains(expected), "{expected} in {text}");
        }
        let gui = connection.arguments(Options {
            x11: true,
            terminal: true,
            ..Options::default()
        });
        assert!(gui.join(" ").contains(" -t -X "));
    }
}
